using System.Text; using System.Text.Json; using System.Net.Http.Headers;
namespace RaceDay.Mvc.Services;
public sealed class RaceDayApiClient {
 readonly HttpClient http; readonly IHttpContextAccessor ctx; static readonly JsonSerializerOptions opts=new(JsonSerializerDefaults.Web);
 public RaceDayApiClient(HttpClient h,IHttpContextAccessor c){http=h;ctx=c;}
 HttpRequestMessage Req(HttpMethod m,string p){var r=new HttpRequestMessage(m,p);var cookie=ctx.HttpContext?.Session.GetString("ApiCookie");if(!string.IsNullOrEmpty(cookie))r.Headers.TryAddWithoutValidation("Cookie",cookie);return r;}
 public async Task<T?> Get<T>(string p){using var r=Req(HttpMethod.Get,p);using var x=await http.SendAsync(r);if(!x.IsSuccessStatusCode)return default;return await x.Content.ReadFromJsonAsync<T>(opts);}
 public async Task<(bool Ok,string Message,T? Data)> Send<T>(HttpMethod m,string p,object? body=null,bool captureCookie=false){using var r=Req(m,p);if(body!=null)r.Content=new StringContent(JsonSerializer.Serialize(body,opts),Encoding.UTF8,"application/json");using var x=await http.SendAsync(r);if(captureCookie&&x.Headers.TryGetValues("Set-Cookie",out var vals)){var c=vals.FirstOrDefault(v=>v.StartsWith(".RaceDay.Session=",StringComparison.OrdinalIgnoreCase));if(c!=null)ctx.HttpContext?.Session.SetString("ApiCookie",c.Split(';')[0]);}var s=await x.Content.ReadAsStringAsync();if(!x.IsSuccessStatusCode)return(false,Error(s)??$"API error {(int)x.StatusCode}.",default);T? d=default;try{if(s.Length>0)d=JsonSerializer.Deserialize<T>(s,opts);}catch{}return(true,"",d);}
 public async Task<(bool Ok,string Message)> SendNoData(HttpMethod m,string p,object? body=null){using var r=Req(m,p);if(body!=null)r.Content=new StringContent(JsonSerializer.Serialize(body,opts),Encoding.UTF8,"application/json");using var x=await http.SendAsync(r);var s=await x.Content.ReadAsStringAsync();return x.IsSuccessStatusCode?(true,""):(false,Error(s)??$"API error {(int)x.StatusCode}.");}
 public async Task<(bool Ok,string Message)> Upload(string p,IFormFile f){using var r=Req(HttpMethod.Post,p);using var c=new MultipartFormDataContent();await using var s=f.OpenReadStream();var sc=new StreamContent(s);sc.Headers.ContentType=new MediaTypeHeaderValue(f.ContentType);c.Add(sc,"File",Path.GetFileName(f.FileName));r.Content=c;using var x=await http.SendAsync(r);var t=await x.Content.ReadAsStringAsync();return x.IsSuccessStatusCode?(true,""):(false,Error(t)??$"Upload failed {(int)x.StatusCode}.");}
 static string? Error(string s){try{using var d=JsonDocument.Parse(s);foreach(var k in new[]{"detail","title","message"})if(d.RootElement.TryGetProperty(k,out var p))return p.GetString();}catch{}return string.IsNullOrWhiteSpace(s)?null:s;}
}